import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Teachers() {
  const [teachersList, setTeachersList] = useState([]);

  // 🟢 ඩේටාබේස් එකෙන් ලයිව් ගුරුවරුන්ගේ දත්ත ඇදගැනීම
  useEffect(() => {
    axios.get('http://localhost:8082/api/view-teachers')
      .then(res => {
        setTeachersList(Array.isArray(res.data) ? res.data : []);
      })
      .catch(err => console.log("Public Teachers Fetch Error:", err));
  }, []);

  return (
    <div style={{ padding: '60px 20px', backgroundColor: '#f8fafc', flex: 1, fontFamily: 'sans-serif' }}>
      <div style={{ maxWidth: '1000px', margin: '0 auto', textAlign: 'center' }}>
        
        <h1 style={{ color: '#15803d', fontSize: '32px', fontWeight: 'bold', margin: '0 0 10px 0' }}>
          Meet Our Expert Lecturers
        </h1>
        <p style={{ color: '#64748b', fontSize: '15px', margin: '0 0 50px 0' }}>
          Highly Qualified Panel of Teachers at Aura Pen Education
        </p>

        {teachersList.length > 0 ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '25px', textAlign: 'left' }}>
            {teachersList.map((t) => (
              <div key={t.id} style={{ backgroundColor: 'white', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: '5px solid #15803d', display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <h3 style={{ margin: 0, color: '#1e293b', fontSize: '18px', fontWeight: 'bold' }}>{t.name}</h3>
                  <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '3px 8px', borderRadius: '6px', fontSize: '11px', fontWeight: 'bold' }}>
                    {t.Subject || 'Faculty'}
                  </span>
                </div>
                
                <div style={{ fontSize: '13px', color: '#64748b', fontStyle: 'italic', marginTop: '2px' }}>
                  🎓 {t.qualifications || 'Expert Educator'}
                </div>
                
                <div style={{ borderTop: '1px solid #f1f5f9', margin: '10px 0' }}></div>
                
                <div style={{ fontSize: '13px', color: '#475569', display: 'flex', alignItems: 'center', gap: '6px' }}>
                  📞 <span>{t.phone_number}</span>
                </div>
                
                <div style={{ fontSize: '13px', color: '#475569', display: 'flex', alignItems: 'center', gap: '6px' }}>
                  ✉️ <span style={{ color: '#64748b' }}>{t.email || 'No official email provided'}</span>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', color: '#94a3b8', fontSize: '14px' }}>
            🧑‍🏫 No expert lecturers registered in the institution database panel yet.
          </div>
        )}

      </div>
    </div>
  );
}
